#nullable enable
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;

namespace Grove.Media.Files;

/// <summary>
/// Module-generated files through the upload pipeline, with exemptions (docs/media.md § 2,
/// ruling 2026-10-05). The caller's access decides as for an upload; scanning is skipped only for
/// a module and type the tenant's options exempt, and the version records why.
/// </summary>
public sealed class MediaGeneratedFiles(
    MediaObjectService files,
    IOptions<MediaScanExemptionOptions> options,
    ILogger<MediaGeneratedFiles> logger) : IMediaGeneratedFiles
{
    public Task<MediaItem> CreateAsync(string module, MediaUpload upload, CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(module);
        ArgumentNullException.ThrowIfNull(upload);
        return files.CreateGeneratedAsync(upload, ExemptReason(module, upload.ClaimedType, upload.Name), cancellationToken);
    }

    public async Task<MediaItem> WriteVersionAsync(string module, string placementId, Stream content, string? claimedType, bool publishWhenClean = true, CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(module);
        var item = await files.GetAsync(placementId, cancellationToken) ?? throw new MediaObjectNotFoundException();
        return await files.ReplaceGeneratedAsync(placementId, content, claimedType, publishWhenClean, ExemptReason(module, claimedType, item.Placement.Name), cancellationToken);
    }

    public bool IsExempt(string module, string? claimedType, string name) => options.Value.IsExempt(module, claimedType, name);

    private string? ExemptReason(string module, string? claimedType, string name)
    {
        if (!IsExempt(module, claimedType, name))
        {
            return null;
        }

        logger.LogDebug("A file generated by {Module} ({Type}) is exempt from scanning.", module, claimedType);
        return $"exempt: generated by {module}";
    }
}
